// Arma la lista de bloques a procesar a partir del índice del agregador
const base = 'https://raw.githubusercontent.com/Feashliaa/job-board-data/main/data/chunks/';

let d = $input.first().json;
if (typeof d.data === 'string') d = JSON.parse(d.data);   // viene como texto
else if (d.data) d = d.data;

return (d.chunks || []).map(nombre => ({ json: { url: base + nombre } }));

// Búsquedas de Google para encontrar empresas que el agregador no tenga
const sitios = ['jobs.ashbyhq.com', 'job-boards.greenhouse.io', 'boards.greenhouse.io', 'jobs.lever.co'];
const terminos = ['"Buenos Aires"', '"Argentina"', '"LATAM"', '"Latin America"'];
const out = [];
for (const s of sitios) for (const t of terminos) out.push({ json: { q: `site:${s} ${t} engineer` } });
return out;

// Saca empresas (slug + plataforma) de los links que devolvió Google
const SLUG = {
  ashby: /jobs\.ashbyhq\.com\/([^\/?#]+)/i,
  greenhouse: /greenhouse\.io\/([^\/?#&]+)/i,
  lever: /jobs\.lever\.co\/([^\/?#]+)/i,
};
const found = {};
for (const item of $input.all()) {
  for (const r of item.json?.organic || []) {
    for (const [ats, re] of Object.entries(SLUG)) {
      const m = re.exec(r.link || '');
      if (!m || m[1] === 'embed') continue;
      const k = `${ats}|${m[1].toLowerCase()}`;
      found[k] ||= { ats, slug: m[1], company: m[1], hq: '', latam_jobs: 1, is_recruiter: false, source: 'google' };
    }
  }
}
return Object.values(found).map(c => ({ json: c }));

// Arma una sola consulta con las empresas descubiertas.
// Los datos viajan como parámetro JSON ($1). La base ignora las repetidas.
const AGENCIES = new Set(['truelogic','olsson','caylent','arionkoder','encora','encora10','nttdatausa','redbee','solvd','jobgether','launchpadtechnologiesinc','nimblegravity','dept','resilientco','santex','factored','devsavant','particle41llc','appnovation','eleks','lokainc','lokajobs','atmosera','bluecoding','telus-digital','toptal','valtech','admios','neoris','techstars57','exadelinc','externaljobboards','onhires','space44','zartis','massive-rocket','applydigital','go-nimbly','rehire','g2i','fluxon','robotsandpencils','webstacks','doitintl','inflect','interviewengineering','muttdata','silver','latamcent','empirical','precisionmedicinegroup','pfm','powerdigitalmarketing','extenteamcareers','applytoaktos','correlationone','squad','emilabs','globant','bairesdev','endava','epam','softtek','turing','andela','agent']);
const LOOKS_LIKE_AGENCY = /consult|staffing|talent|recruit|outsourc|nearshore|jobboard|careers$|jobs$/i;
const nice = s => String(s).replace(/[-_]+/g, ' ').replace(/\b\w/g, ch => ch.toUpperCase());

const acc = {};
for (const it of $input.all()) {
  const c = it.json;
  if (!c.slug || !c.ats) continue;
  const k = `${c.ats.toLowerCase()}|${c.slug.toLowerCase()}`;
  const a = acc[k] ||= { ...c, latam_jobs: 0, is_recruiter: false };
  a.latam_jobs += c.latam_jobs || 0;
  a.is_recruiter = a.is_recruiter || c.is_recruiter;
  if (!a.hq && c.hq) a.hq = c.hq;
}

const rows = Object.values(acc).map(c => {
  // en Workday el slug es "empresa/sitio": solo importa la empresa
  const slug = c.slug.toLowerCase().split('/')[0];
  const agency = AGENCIES.has(slug) || c.is_recruiter || LOOKS_LIKE_AGENCY.test(slug);
  return {
    slug: c.slug,
    ats: c.ats,
    name: nice(c.company || c.slug),
    hq: c.hq || null,
    careers_url: c.careers_url || null,
    source: c.source || null,
    status: agency ? 'inactive' : 'active',
  };
});

const sql = `
INSERT INTO companies (slug, ats, name, hq, careers_url, source, status)
SELECT v.slug, v.ats::job_source, v.name, v.hq, v.careers_url, v.source, v.status::company_status
FROM jsonb_to_recordset($1::jsonb) AS v(
  slug text, ats text, name text, hq text, careers_url text, source text, status text
)
ON CONFLICT (ats, slug) DO UPDATE SET
  hq = COALESCE(companies.hq, EXCLUDED.hq),
  careers_url = COALESCE(companies.careers_url, EXCLUDED.careers_url)
RETURNING (xmax = 0) AS inserted, slug, ats`;

return [{ json: { sql, params: JSON.stringify(rows), rows: rows.length } }];
